1559	fn evict_lru(cache: &mut CacheFile, max_bytes: usize) -> Result<String> {
1560	    let mut ordered: Vec<(Utf8PathBuf, u64)> = cache.entries.iter()
1561	        .map(|(p, e)| (p.clone(), e.last_accessed_ns)).collect();
1562	    ordered.sort_by_key(|(_, ts)| *ts);
1563	    let chunk = (ordered.len() / 10).max(1);
1564	    let mut in_chunk: usize = 0;
1565	    for (path, _) in &ordered {
1566	        if in_chunk > 0 && in_chunk % chunk == 0 {
1567	            let json = serde_json::to_string_pretty(cache)?;
1568	            if json.len() <= max_bytes {
1569	                return Ok(json);
1570	            }
1571	        }
1572	        cache.entries.remove(path);
1573	        in_chunk += 1;
1574	    }
1575	    serde_json::to_string_pretty(cache).map_err(Into::into)
1576	}
