1	use std::time::Duration;
2	
3	use crate::hints::Hint;
4	use crate::recovery::RecoveryHint;
5	
6	/// Classification of a `michi::Error` for routing and display decisions.
7	#[derive(Debug, Clone, Copy, PartialEq, Eq)]
8	#[cfg_attr(feature = "schemars", derive(schemars::JsonSchema))]
9	#[non_exhaustive]
10	pub enum ErrorClass {
11	    /// The caller provided invalid input. Do not retry.
12	    User,
13	    /// A downstream or infrastructure failure that is not the caller's direct
14	    /// error and is not expected to self-resolve without intervention. Note:
15	    /// `RateLimited` falls here when `retryable: false` — the caller may have
16	    /// contributed to the rate-limit condition, but at classification time the
17	    /// error is not self-resolving. michi does not recommend automatic retry
18	    /// for `Internal` errors.
19	    Internal,
20	    /// A transient failure expected to resolve without intervention.
21	    Transient,
22	}
23	
24	/// Wraps a value so its inner content is omitted from `Debug` and `Display`.
25	#[derive(Clone)]
26	pub struct Sensitive<T>(pub T);
27	
28	impl<T> std::fmt::Debug for Sensitive<T> {
29	    fn fmt(&self, f: &mut std::fmt::Formatter<'_>) -> std::fmt::Result {
30	        f.write_str("<redacted>")
31	    }
32	}
33	
34	impl<T> std::fmt::Display for Sensitive<T> {
35	    fn fmt(&self, f: &mut std::fmt::Formatter<'_>) -> std::fmt::Result {
36	        f.write_str("<redacted>")
37	    }
38	}
39	
40	/// The specific kind of domain error.
41	#[derive(Debug, Clone, Copy, PartialEq, Eq)]
42	#[cfg_attr(feature = "schemars", derive(schemars::JsonSchema))]
43	#[non_exhaustive]
44	pub enum ErrorCode {
45	    /// Bad parameters.
46	    InvalidInput,
47	    /// Resource absent.
48	    NotFound,
49	    /// Auth failure.
50	    Unauthorized,
51	    /// Permission denied.
52	    Forbidden,
53	    /// Resource state mismatch.
54	    Conflict,
55	    /// Rate limited (HTTP 429).
56	    RateLimited,
57	    /// Service unavailable (HTTP 503).
58	    Unavailable,
59	    /// Request timed out.
60	    Timeout,
61	    /// Downstream/external failure.
62	    ExternalFailure,
63	}
64	
65	impl ErrorCode {
66	    /// The snake_case label used in rendered output.
67	    #[must_use]
68	    pub fn label(&self) -> &'static str {
69	        match self {
70	            Self::InvalidInput => "invalid_input",
71	            Self::NotFound => "not_found",
72	            Self::Unauthorized => "unauthorized",
73	            Self::Forbidden => "forbidden",
74	            Self::Conflict => "conflict",
75	            Self::RateLimited => "rate_limited",
76	            Self::Unavailable => "unavailable",
77	            Self::Timeout => "timeout",
78	            Self::ExternalFailure => "external_failure",
79	        }
80	    }
81	
82	    /// Whether this code is conventionally retryable.
83	    #[must_use]
84	    pub fn is_retryable_by_default(&self) -> bool {
85	        matches!(self, Self::RateLimited | Self::Unavailable | Self::Timeout | Self::ExternalFailure)
86	    }
87	
88	    /// The default [`ErrorClass`] for this code, independent of `DomainError.retryable`.
89	    ///
90	    /// Infrastructure codes (`RateLimited`, `Unavailable`, `Timeout`,
91	    /// `ExternalFailure`) return `Internal`; caller-fault codes return `User`.
92	    /// Used by [`Error::class()`].
93	    #[must_use]
94	    pub fn default_class(&self) -> ErrorClass {
95	        match self {
96	            Self::InvalidInput | Self::NotFound | Self::Unauthorized | Self::Forbidden | Self::Conflict => {
97	                ErrorClass::User
98	            }
99	            Self::RateLimited | Self::Unavailable | Self::Timeout | Self::ExternalFailure => ErrorClass::Internal,
100	        }
101	    }
102	}
103	
104	/// A domain-level error.
105	#[derive(Debug, Clone)]
106	#[cfg_attr(feature = "schemars", derive(schemars::JsonSchema))]
107	#[non_exhaustive]
108	pub struct DomainError {
109	    /// The error classification.
110	    pub code: ErrorCode,
111	    /// Human-readable message.
112	    pub message: String,
113	    /// Contextual hints, rendered as a trailing `help[N]:` block.
114	    pub hints: Vec<Hint>,
115	    /// Optional structured recovery hint.
116	    pub recovery: Option<RecoveryHint>,
117	    /// Whether this error is safe to retry.
118	    pub retryable: bool,
119	    /// Parsed `Retry-After` delay, if known.
120	    pub retry_after: Option<Duration>,
121	}
122	
123	impl DomainError {
124	    /// Create a domain error.
125	    pub fn new(code: ErrorCode, message: impl Into<String>) -> Self {
126	        Self {
127	            retryable: code.is_retryable_by_default(),
128	            code,
129	            message: message.into(),
130	            hints: Vec::new(),
131	            recovery: None,
132	            retry_after: None,
133	        }
134	    }
135	
136	    /// Append a contextual hint.
137	    #[must_use]
138	    pub fn hint(mut self, hint: impl Into<String>) -> Self {
139	        self.hints.push(Hint::new(hint));
140	        self
141	    }
142	
143	    /// Attach a structured recovery hint.
144	    #[must_use]
145	    pub fn recovery(mut self, r: RecoveryHint) -> Self {
146	        self.recovery = Some(r);
147	        self
148	    }
149	
150	    /// Override the default retryability for this error instance.
151	    #[must_use]
152	    pub fn retryable(mut self, retryable: bool) -> Self {
153	        self.retryable = retryable;
154	        self
155	    }
156	
157	    /// Attach a `Retry-After` delay.
158	    #[must_use]
159	    pub fn retry_after(mut self, d: Duration) -> Self {
160	        self.retry_after = Some(d);
161	        self
162	    }
163	
164	    /// The process exit code to use when this error is fatal. Always `1`.
165	    #[must_use]
166	    pub fn exit_code(&self) -> i32 {
167	        1
168	    }
169	
170	    /// Render to an agent-readable KV block with exit code, hints, and recovery.
171	    #[must_use]
172	    pub fn render(&self) -> String {
173	        let mut out = String::with_capacity(64 + self.message.len() + self.hints.len() * 50);
174	        out.push_str("error: ");
175	        out.push_str(self.code.label());
176	        out.push_str("\nmessage: ");
177	        out.push_str(&self.message);
178	        out.push_str("\nexit_code: 1\n");
179	        crate::hints::append_hints(&mut out, &self.hints);
180	        if let Some(r) = &self.recovery {
181	            crate::recovery::append_recovery(&mut out, std::slice::from_ref(r));
182	        }
183	        out
184	    }
185	
186	    /// Render formatted for GitHub Actions workflow annotations (`::error title=code::message`).
187	    ///
188	    /// Newlines and carriage returns are percent-encoded (`%0A`, `%0D`) to
189	    /// keep the annotation on a single line as required by the Actions runner.
190	    #[must_use]
191	    pub fn render_github_annotation(&self) -> String {
192	        format!("::error title={}::{}", self.code.label(), self.message.replace('\n', "%0A").replace('\r', "%0D"))
193	    }
194	
195	    /// Render as a JSON object matching `AgentResponse::render_json()` shape.
196	    ///
197	    /// Keys: `isError`, `error`, `message`, `retryable`, `hints`, `recovery`.
198	    /// Client code reading `structured_content` should not need two schemas.
199	    #[must_use]
200	    pub fn render_json(&self) -> String {
201	        let hints_est: usize = self.hints.iter().map(|h| h.as_str().len() + 4).sum();
202	        let recovery_est: usize = self.recovery.as_ref().map_or(0, |r| {
203	            50 + r.tool.len()
204	                + r.params.iter().map(|_| 20usize).sum::<usize>()
205	                + r.reason.as_ref().map_or(0, |s| s.len() + 12)
206	        });
207	        let mut out = String::with_capacity(128 + self.message.len() + hints_est + recovery_est);
208	        out.push_str("{\"isError\":true,\"error\":");
209	        crate::kv::json_escape_str(&mut out, self.code.label());
210	        out.push_str(",\"message\":");
211	        crate::kv::json_escape_str(&mut out, &self.message);
212	        out.push_str(",\"retryable\":");
213	        out.push_str(if self.retryable { "true" } else { "false" });
214	        out.push_str(",\"hints\":[");
215	        for (i, h) in self.hints.iter().enumerate() {
216	            if i > 0 {
217	                out.push(',');
218	            }
219	            crate::kv::json_escape_str(&mut out, h.as_str());
220	        }
221	        out.push_str("],\"recovery\":");
222	        match &self.recovery {
223	            None => out.push_str("null"),
224	            Some(r) => {
225	                out.push_str("{\"tool\":");
226	                crate::kv::json_escape_str(&mut out, &r.tool);
227	                out.push_str(",\"params\":{");
228	                for (j, (k, v)) in r.params.iter().enumerate() {
229	                    if j > 0 {
230	                        out.push(',');
231	                    }
232	                    crate::kv::json_escape_str(&mut out, k);
233	                    out.push(':');
234	                    crate::kv::kv_value_to_json(&mut out, v);
235	                }
236	                out.push('}');
237	                if let Some(reason) = &r.reason {
238	                    out.push_str(",\"reason\":");
239	                    crate::kv::json_escape_str(&mut out, reason);
240	                }
241	                out.push('}');
242	            }
243	        }
244	        out.push('}');
245	        out
246	    }
247	
248	    /// Build an MCP [`CallToolResult`] representing this error.
249	    ///
250	    /// Sets `is_error: true`. Text content uses [`DomainError::render()`];
251	    /// `structured_content` uses [`DomainError::render_json()`].
252	    ///
253	    /// **Canonical path:** call this directly when you hold a `DomainError`.
254	    /// Do not wrap in `AgentResponse::as_error()` — that loses typed fields.
255	    #[must_use]
256	    pub fn to_call_tool_result(&self) -> crate::mcp::CallToolResult {
257	        crate::mcp::CallToolResult {
258	            content: vec![crate::mcp::ContentBlock {
259	                text: self.render(),
260	                audience: vec![crate::audience::Audience::Assistant],
261	            }],
262	            is_error: true,
263	            structured_content: self.render_json(),
264	        }
265	    }
266	}
267	
268	impl std::fmt::Display for DomainError {
269	    fn fmt(&self, f: &mut std::fmt::Formatter<'_>) -> std::fmt::Result {
270	        write!(f, "{}: {}", self.code.label(), self.message)
271	    }
272	}
273	
274	impl std::error::Error for DomainError {}
275	
276	#[cfg(feature = "miette")]
277	impl miette::Diagnostic for DomainError {
278	    fn code<'a>(&'a self) -> Option<Box<dyn std::fmt::Display + 'a>> {
279	        Some(Box::new(self.code.label()))
280	    }
281	
282	    fn help<'a>(&'a self) -> Option<Box<dyn std::fmt::Display + 'a>> {
283	        if self.hints.is_empty() {
284	            None
285	        } else {
286	            Some(Box::new(self.hints.iter().map(|h| h.as_str()).collect::<Vec<_>>().join("\n")))
287	        }
288	    }
289	}
290	
291	/// The unified error type for the michi crate.
292	#[derive(Debug, thiserror::Error)]
293	#[non_exhaustive]
294	pub enum Error {
295	    /// Invalid or malformed input.
296	    #[error("Invalid input: {0}")]
297	    InvalidInput(String),
298	
299	    /// A required resource was not found.
300	    #[error("Not found: {0}")]
301	    NotFound(String),
302	
303	    /// A classified domain error with hints, recovery, and retry metadata.
304	    #[error("{}: {}", .0.code.label(), .0.message)]
305	    Domain(#[from] DomainError),
306	}
307	
308	impl Error {
309	    /// Render this error as an agent-readable plain-text string.
310	    #[must_use]
311	    pub fn render(&self) -> String {
312	        match self {
313	            Self::Domain(d) => d.render(),
314	            other => format!("error: {other}"),
315	        }
316	    }
317	
318	    /// The process exit code to use when this error is fatal.
319	    #[must_use]
320	    pub fn exit_code(&self) -> i32 {
321	        1
322	    }
323	
324	    /// Classify this error for routing decisions.
325	    #[must_use]
326	    pub fn class(&self) -> ErrorClass {
327	        match self {
328	            Self::Domain(d) if d.retryable => ErrorClass::Transient,
329	            Self::Domain(d) => d.code.default_class(),
330	            Self::InvalidInput(_) | Self::NotFound(_) => ErrorClass::User,
331	        }
332	    }
333	
334	    /// Whether this error is safe to retry automatically.
335	    #[must_use]
336	    pub fn is_retryable(&self) -> bool {
337	        matches!(self.class(), ErrorClass::Transient)
338	    }
339	}
340	
341	#[cfg(test)]
342	mod tests {
343	    use super::*;
344	
345	    #[test]
346	    fn domain_error_render_json_basic() {
347	        let err = DomainError::new(ErrorCode::NotFound, "Item 42 not found");
348	        let json = err.render_json();
349	        assert!(json.contains("\"isError\":true"), "got: {json}");
350	        assert!(json.contains("\"error\":"), "got: {json}");
351	        assert!(json.contains("\"message\":\"Item 42 not found\""), "got: {json}");
352	        assert!(json.contains("\"retryable\":false"), "got: {json}");
353	        assert!(json.contains("\"hints\":["), "got: {json}");
354	    }
355	
356	    #[test]
357	    fn domain_error_render_json_includes_hints() {
358	        let err = DomainError::new(ErrorCode::NotFound, "not found").hint("Try searching with get_items");
359	        let json = err.render_json();
360	        assert!(json.contains("\"hints\""), "got: {json}");
361	        assert!(json.contains("Try searching"), "got: {json}");
362	    }
363	
364	    #[test]
365	    fn domain_error_to_call_tool_result_is_error() {
366	        let err = DomainError::new(ErrorCode::Unavailable, "down");
367	        let result = err.to_call_tool_result();
368	        assert!(result.is_error);
369	        assert!(!result.content.is_empty());
370	    }
371	
