+    fn query_plan_absence_of_default_pinned() {
+        assert!(!DefaultProbe::<QueryPlan>::IS);
+        // Positive control (proves the probe itself isn't just always
+        // false): usize implements Default.
+        assert!(DefaultProbe::<usize>::IS);
+    }
